import{_ as e,o as a,c as r,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const P=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Bugs.md","filePath":"manual-zh/Bugs.md","lastUpdated":1785684581000}'),s={name:"manual-zh/Bugs.md"};function n(l,t,o,u,i,g){return a(),r("div",null,[...t[0]||(t[0]=[p('<h2 id="_22-缺陷-bugs" tabindex="-1">22 缺陷（Bugs） <a class="header-anchor" href="#_22-缺陷-bugs" aria-label="Permalink to &quot;22 缺陷（Bugs）&quot;">​</a></h2><p>偶尔你可能会在 PSPP 中遇到缺陷（bug）。</p><p>如果你认为自己发现了一个缺陷，请先确认它确实是一个缺陷。有时看似缺陷的问题，其实是对程序使用方式的误解。如果不确定，可以在 pspp-users 邮件列表上寻求建议。该邮件列表的信息见 <a href="http://lists.gnu.org/mailman/listinfo/pspp-users" target="_blank" rel="noreferrer">http://lists.gnu.org/mailman/listinfo/pspp-users</a>。</p><p>试用 PSPP 的最新版本也很有价值，因为问题可能已被修复。访问 <a href="https://www.gnu.org/s/pspp" target="_blank" rel="noreferrer">the PSPP website</a> 总能找到 PSPP 的最新版本。你可能从下游打包方（例如某个 GNU/Linux 发行版）获得了 PSPP；如果你的下游软件包不是最新，请请求分发方更新到最新版本。</p><p>如果问题在最新版本中仍然存在，请检查它是否已被报告过。已报告的问题列于 <a href="http://savannah.gnu.org/bugs/?group=pspp" target="_blank" rel="noreferrer">http://savannah.gnu.org/bugs/?group=pspp</a>。如果已经报告过，你可以考虑补充一条包含额外信息的评论，或者仅仅说明你也遇到了该问题，因为 PSPP 开发者往往倾向于处理对大量用户重要的议题。</p><p>有关各语言特性的已知问题，请参见 <a href="./Language">Language</a> 中的相关章节。</p><p>如果问题存在于较新版本中且尚未被报告，请报告它。</p><h3 id="_22-1-如何报告缺陷" tabindex="-1">22.1 如何报告缺陷 <a class="header-anchor" href="#_22-1-如何报告缺陷" aria-label="Permalink to &quot;22.1 如何报告缺陷&quot;">​</a></h3><p>提交缺陷报告的最佳方式是使用网页 <a href="http://savannah.gnu.org/bugs/?group=pspp" target="_blank" rel="noreferrer">http://savannah.gnu.org/bugs/?group=pspp</a>。或者，也可以通过电子邮件将缺陷报告发送至 <a href="mailto:bug-gnu-pspp@gnu.org" target="_blank" rel="noreferrer">bug-gnu-pspp@gnu.org</a>。</p><p>一份高质量的缺陷报告能让开发者理解、复现并最终修复问题。我们建议包含以下内容：</p><ul><li>你遇到该问题的 PSPP 版本。了解 PSPP 是如何构建的一些信息通常也很有帮助。</li></ul><p>使用 PSPP 命令语法时，<code>SHOW SYSTEM.</code> 会输出我们通常所需的全部信息。在 PSPPIRE 图形界面中，Help → System Info（帮助 → 系统信息）会产生相同的输出。</p><ul><li>运行它的操作系统和计算机类型。</li><li>导致该问题的语法示例，或者如果是用户界面问题，复现所需的操作步骤。截图有助于报告图形用户界面中的缺陷，尤其是因为 GUI 缺陷可能在某些系统上出现而在其他系统上不出现，但它们通常无助于修复其他类型的缺陷。</li><li>你认为哪里出错的说明：发生了什么你不期望的事，而你又期望发生什么？包括 PSPP 输出的任何错误信息。</li></ul><p>下面是一份包含所有上述要素的缺陷报告示例：</p><table tabindex="0"><thead><tr><th>Version</th><th>GNU pspp 2.0.1-gff8d3d</th></tr></thead><tbody><tr><td>Host System</td><td>x86_64-pc-linux-gnu</td></tr><tr><td>Build System</td><td>x86_64-pc-linux-gnu</td></tr><tr><td>Locale Directory</td><td>/usr/local/share/locale</td></tr><tr><td>Journal File</td><td>/home/pspp/.local/state/pspp/pspp.jnl</td></tr><tr><td>Compiler Version</td><td>10.2.1 20210110</td></tr></tbody></table><p>另一方面，下面这份缺陷报告提供的信息不足以让 PSPP 开发者理解问题。这意味着开发者无法在多轮追问之外识别或修复问题，这给报告者和开发者都增加了工作量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I downloaded the latest version of PSPP and entered a sequence of numbers, but when I analyse them it gives the wrong output.</span></span></code></pre></div><p>PSPP 开发者重视所有用户的反馈，但无法承诺立即回应。缺陷报告并非咨询或支持服务，不过你可以私下安排此类服务。由于 PSPP 是自由软件，咨询师可以获取提供此类支持所需的信息。</p><p>对于一般咨询或帮助，请使用 <a href="http://lists.gnu.org/mailman/listinfo/pspp-users" target="_blank" rel="noreferrer">pspp-users mailing list</a>，而不要使用缺陷邮件列表或缺陷跟踪器。</p><p>PSPP 缺陷跟踪器和缺陷报告邮件列表都是公开的。如需私下报告 GNU PSPP 中的安全漏洞，请将报告发送至私密邮件列表 <a href="mailto:pspp-security@gnu.org" target="_blank" rel="noreferrer">pspp-security@gnu.org</a>。PSPP 开发者会帮助你评估报告，并在公开披露前修复问题。</p>',20)])])}const h=e(s,[["render",n]]);export{P as __pageData,h as default};
